3: export class Option {
4:   /**
5:    * Initialize a new `Option` with the given `flags` and `description`.
6:    *
7:    * @param {string} flags
8:    * @param {string} [description]
9:    */
10: 
11:   constructor(flags, description) {
12:     this.flags = flags;
13:     this.description = description || '';
14: 
15:     this.required = flags.includes('<'); // A value must be supplied when the option is specified.
16:     this.optional = flags.includes('['); // A value is optional when the option is specified.
17:     // variadic test ignores <value,...> et al which might be used to describe custom splitting of single argument
18:     this.variadic = /\w\.\.\.[>\]]$/.test(flags); // The option can take multiple values.
19:     this.mandatory = false; // The option must have a value after parsing, which usually means it must be specified on command line.
20:     const optionFlags = splitOptionFlags(flags);
21:     this.short = optionFlags.shortFlag; // May be a short flag, undefined, or even a long flag (if option has two long flags).
22:     this.long = optionFlags.longFlag;
23:     this.negate = false;
24:     if (this.long) {
25:       this.negate = this.long.startsWith('--no-');
26:     }
27:     this.defaultValue = undefined;
28:     this.defaultValueDescription = undefined;
29:     this.presetArg = undefined;
30:     this.envVar = undefined;
31:     this.parseArg = undefined;
32:     this.hidden = false;
33:     this.argChoices = undefined;
34:     this.conflictsWith = [];
35:     this.implied = undefined;
36:     this.helpGroupHeading = undefined; // soft initialised when option added to command
37:   }
38: 
39:   /**
40:    * Set the default value, and optionally supply the description to be displayed in the help.
41:    *
42:    * @param {*} value
43:    * @param {string} [description]
44:    * @return {Option}
45:    */
46: 
47:   default(value, description) {
48:     this.defaultValue = value;
49:     this.defaultValueDescription = description;
50:     return this;
51:   }
52: 
53:   /**
54:    * Preset to use when option used without option-argument, especially optional but also boolean and negated.
55:    * The custom processing (parseArg) is called.
56:    *
57:    * @example
58:    * new Option('--color').default('GREYSCALE').preset('RGB');
59:    * new Option('--donate [amount]').preset('20').argParser(parseFloat);
60:    *
61:    * @param {*} arg
62:    * @return {Option}
63:    */
64: 
65:   preset(arg) {
66:     this.presetArg = arg;
67:     return this;
68:   }
69: 
70:   /**
71:    * Add option name(s) that conflict with this option.
72:    * An error will be displayed if conflicting options are found during parsing.
73:    *
74:    * @example
75:    * new Option('--rgb').conflicts('cmyk');
76:    * new Option('--js').conflicts(['ts', 'jsx']);
77:    *
78:    * @param {(string | string[])} names
79:    * @return {Option}
80:    */
81: 
82:   conflicts(names) {
83:     this.conflictsWith = this.conflictsWith.concat(names);
84:     return this;
85:   }
86: 
87:   /**
88:    * Specify implied option values for when this option is set and the implied options are not.
89:    *
90:    * The custom processing (parseArg) is not called on the implied values.
91:    *
92:    * @example
93:    * program
94:    *   .addOption(new Option('--log', 'write logging information to file'))
95:    *   .addOption(new Option('--trace', 'log extra details').implies({ log: 'trace.txt' }));
96:    *
97:    * @param {object} impliedOptionValues
98:    * @return {Option}
99:    */
100:   implies(impliedOptionValues) {
101:     let newImplied = impliedOptionValues;
102:     if (typeof impliedOptionValues === 'string') {
103:       // string is not documented, but easy mistake and we can do what user probably intended.
104:       newImplied = { [impliedOptionValues]: true };
105:     }
106:     this.implied = Object.assign(this.implied || {}, newImplied);
107:     return this;
108:   }
109: 
110:   /**
111:    * Set environment variable to check for option value.
112:    *
113:    * An environment variable is only used if when processed the current option value is
114:    * undefined, or the source of the current value is 'default' or 'config' or 'env'.
115:    *
116:    * @param {string} name
117:    * @return {Option}
118:    */
119: 
120:   env(name) {
121:     this.envVar = name;
122:     return this;
123:   }
124: 
125:   /**
126:    * Set the custom handler for processing CLI option arguments into option values.
127:    *
128:    * @param {Function} [fn]
129:    * @return {Option}
130:    */
131: 
132:   argParser(fn) {
133:     this.parseArg = fn;
134:     return this;
135:   }
136: 
137:   /**
138:    * Whether the option is mandatory and must have a value after parsing.
139:    *
140:    * @param {boolean} [mandatory=true]
141:    * @return {Option}
142:    */
143: 
144:   makeOptionMandatory(mandatory = true) {
145:     this.mandatory = !!mandatory;
146:     return this;
147:   }
148: 
149:   /**
150:    * Hide option in help.
151:    *
152:    * @param {boolean} [hide=true]
153:    * @return {Option}
154:    */
155: 
156:   hideHelp(hide = true) {
157:     this.hidden = !!hide;
158:     return this;
159:   }
160: 
161:   /**
162:    * @package
163:    */
164: 
165:   _collectValue(value, previous) {
166:     if (previous === this.defaultValue || !Array.isArray(previous)) {
167:       return [value];
168:     }
169: 
170:     previous.push(value);
171:     return previous;
172:   }
173: 
174:   /**
175:    * Only allow option value to be one of choices.
176:    *
177:    * @param {string[]} values
178:    * @return {Option}
179:    */
180: 
181:   choices(values) {
182:     this.argChoices = values.slice();
183:     this.parseArg = (arg, previous) => {
184:       if (!this.argChoices.includes(arg)) {
185:         throw new InvalidArgumentError(
186:           `Allowed choices are ${this.argChoices.join(', ')}.`,
187:         );
188:       }
189:       if (this.variadic) {
190:         return this._collectValue(arg, previous);
191:       }
192:       return arg;
193:     };
194:     return this;
195:   }
196: 
197:   /**
198:    * Return option name.
199:    *
200:    * @return {string}
201:    */
202: 
203:   name() {
204:     if (this.long) {
205:       return this.long.replace(/^--/, '');
206:     }
207:     return this.short.replace(/^-/, '');
208:   }
209: 
210:   /**
211:    * Return option name, in a camelcase format that can be used
212:    * as an object attribute key.
213:    *
214:    * @return {string}
215:    */
216: 
217:   attributeName() {
218:     return camelcase(this.name());
219:   }
220: 
221:   /**
222:    * Set the help group heading.
223:    *
224:    * @param {string} heading
225:    * @return {Option}
226:    */
227:   helpGroup(heading) {
228:     this.helpGroupHeading = heading;
229:     return this;
230:   }
231: 
232:   /**
233:    * Check if `arg` matches the short or long flag.
234:    *
235:    * @param {string} arg
236:    * @return {boolean}
237:    * @package
238:    */
239: 
240:   is(arg) {
241:     return this.short === arg || this.long === arg;
242:   }
243: 
244:   /**
245:    * Return whether a boolean option.
246:    *
247:    * Options are one of boolean, negated, required argument, or optional argument.
248:    *
249:    * @return {boolean}
250:    * @package
251:    */
252: 
253:   isBoolean() {
254:     return !this.required && !this.optional && !this.negate;
255:   }
256: }
