258: /**
259:  * This class is to make it easier to work with dual options, without changing the existing
260:  * implementation. We support separate dual options for separate positive and negative options,
261:  * like `--build` and `--no-build`, which share a single option value. This works nicely for some
262:  * use cases, but is tricky for others where we want separate behaviours despite
263:  * the single shared option value.
264:  */
265: export class DualOptions {
266:   /**
267:    * @param {Option[]} options
268:    */
269:   constructor(options) {
270:     this.positiveOptions = new Map();
271:     this.negativeOptions = new Map();
272:     this.dualOptions = new Set();
273:     options.forEach((option) => {
274:       if (option.negate) {
275:         this.negativeOptions.set(option.attributeName(), option);
276:       } else {
277:         this.positiveOptions.set(option.attributeName(), option);
278:       }
279:     });
280:     this.negativeOptions.forEach((value, key) => {
281:       if (this.positiveOptions.has(key)) {
282:         this.dualOptions.add(key);
283:       }
284:     });
285:   }
286: 
287:   /**
288:    * Did the value come from the option, and not from possible matching dual option?
289:    *
290:    * @param {*} value
291:    * @param {Option} option
292:    * @returns {boolean}
293:    */
294:   valueFromOption(value, option) {
295:     const optionKey = option.attributeName();
296:     if (!this.dualOptions.has(optionKey)) return true;
297: 
298:     // Use the value to deduce if (probably) came from the option.
299:     const preset = this.negativeOptions.get(optionKey).presetArg;
300:     const negativeValue = preset !== undefined ? preset : false;
301:     return option.negate === (negativeValue === value);
302:   }
303: }
